use crate::{expr::{Block, Expr, Statement}, types::TypeInfo};
use super::{MlirBuilder, Ref, RefKind};

impl<'a> MlirBuilder<'a> {
    pub(crate) fn lower_block(&mut self,b:&Block,expected:Option<&TypeInfo>)->Result<Option<Ref>,String>{for s in &b.statements{self.statement(s)?}if let Some(e)=&b.result{Ok(Some(self.lower_expr(e,expected.ok_or("block result has no expected type")?)?))}else{if expected.is_some(){return Err("block has no result expression".into())}Ok(None)}}
    pub(crate) fn statement(&mut self,s:&Statement)->Result<(),String>{match s{Statement::Let{local,type_info,value,..}=>{if *local!=self.local_count{return Err(format!("invalid local index {}",local))}let p=self.alloca(type_info);let v=self.lower_expr(value,type_info)?;self.store(&v.name,&p,type_info);self.refs.push(Ref{name:p,ty:type_info.clone(),kind:RefKind::Address});self.local_count+=1},Statement::Assign{local,value}=>{let idx=self.closure.arguments.len()+*local;let r=self.refs.get(idx).cloned().ok_or("local index out of bounds")?;let v=self.lower_expr(value,&r.ty)?;self.store(&v.name,&r.name,&r.ty)},Statement::AssignIndex{sequence,index,value}=>{let p=self.index_address(sequence,index)?;let v=self.lower_expr(value,&p.ty)?;self.store(&v.name,&p.name,&p.ty)},Statement::While{condition,body}=>{let cb=self.block("while_cond");let bb=self.block("while_body");let xb=self.block("while_exit");self.emit_branch(&cb);self.label(&cb);let c=self.lower_expr(condition,&TypeInfo::Bool)?;self.emit_cond(&c.name,&bb,&xb);self.label(&bb);self.lower_block(body,None)?;if !self.current_terminated{self.emit_branch(&cb)}self.label(&xb)},Statement::For{local,type_info,start,end,inclusive,body}=>{let p=self.alloca(type_info);let s=self.lower_expr(start,type_info)?;self.store(&s.name,&p,type_info);let cb=self.block("for_cond");let bb=self.block("for_body");let ib=self.block("for_inc");let xb=self.block("for_exit");self.emit_branch(&cb);self.label(&cb);let cur=self.load(&p,type_info);let ev=self.lower_expr(end,type_info)?;let cmp=self.value();let pred=if type_info.is_float(){if *inclusive{"ole"}else{"olt"}}else if type_info.is_unsigned_integer(){if *inclusive{"ule"}else{"ult"}}else if *inclusive{"sle"}else{"slt"};let op=if type_info.is_float(){"fcmp"}else{"icmp"};self.text.push_str(&format!("    {} = llvm.{} \"{}\", {}, {} : {}\n",cmp,op,pred,cur,ev.name,Self::ty(type_info)));self.emit_cond(&cmp,&bb,&xb);self.label(&bb);self.refs.push(Ref{name:p.clone(),ty:type_info.clone(),kind:RefKind::Address});self.local_count+=1;self.lower_block(body,None)?;self.local_count-=1;self.refs.pop();if !self.current_terminated{self.emit_branch(&ib)}self.label(&ib);let cur=self.load(&p,type_info);let one=self.c_int("1",&Self::ty(type_info));let n=self.value();let op=if type_info.is_float(){"fadd"}else{"add"};self.text.push_str(&format!("    {} = llvm.{} {}, {} : {}\n",n,op,cur,one,Self::ty(type_info)));self.store(&n,&p,type_info);self.emit_branch(&cb);self.label(&xb)}}Ok(())}
}
